    "css": ".absolute {\n  position: absolute\n}\n\n.relative {\n  position: relative\n}\n\n.left-\\[3\\%\\] {\n  left: 3%\n}\n\n.top-1\\/2 {\n  top: 50%\n}\n\n.block {\n  display: block\n}\n\n.hidden {\n  display: none\n}\n\n.aspect-\\[2\\/0\\.75\\] {\n  aspect-ratio: 2/0.75\n}\n\n.aspect-square {\n  aspect-ratio: 1 / 1\n}\n\n.h-\\[90\\%\\] {\n  height: 90%\n}\n\n.w-20 {\n  width: 5rem\n}\n\n.-translate-y-1\\/2 {\n  --tw-translate-y: -50%;\n  transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))\n}\n\n.rotate-180 {\n  --tw-rotate: 180deg;\n  transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))\n}\n\n.cursor-pointer {\n  cursor: pointer\n}\n\n.rounded-full {\n  border-radius: 9999px\n}\n\n.bg-white {\n  --tw-bg-opacity: 1;\n  background-color: rgb(255 255 255 / var(--tw-bg-opacity))\n}\n\n.bg-gradient-to-r {\n  background-image: linear-gradient(to right, var(--tw-gradient-stops))\n}\n\n.from-red-600 {\n  --tw-gradient-from: #dc2626 var(--tw-gradient-from-position);\n  --tw-gradient-to: rgb(220 38 38 / 0) var(--tw-gradient-to-position);\n  --tw-gradient-stops: var(--tw-gradient-from), var(--tw-gradient-to)\n}\n\n.to-green-600 {\n  --tw-gradient-to: #16a34a var(--tw-gradient-to-position)\n}\n\n.bg-\\[length\\:100\\%_100\\%\\] {\n  background-size: 100% 100%\n}\n\n.shadow-2xl {\n  --tw-shadow: 0 25px 50px -12px rgb(0 0 0 / 0.25);\n  --tw-shadow-colored: 0 25px 50px -12px var(--tw-shadow-color);\n  box-shadow: var(--tw-ring-offset-shadow, 0 0 #0000), var(--tw-ring-shadow, 0 0 #0000), var(--tw-shadow)\n}\n\n.shadow-purple-300 {\n  --tw-shadow-color: #d8b4fe;\n  --tw-shadow: var(--tw-shadow-colored)\n}\n\n.transition-all {\n  transition-property: all;\n  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);\n  transition-duration: 150ms\n}\n\n.duration-500 {\n  transition-duration: 500ms\n}\n\n.hover\\:bg-\\[length\\:100\\%_500\\%\\]:hover {\n  background-size: 100% 500%\n}\n\n.focus\\:bg-\\[length\\:100\\%_500\\%\\]:focus {\n  background-size: 100% 500%\n}\n\n.peer\\/input:checked ~ .peer-checked\\/input\\:left-\\[63\\%\\] {\n  left: 63%\n}\n\n.peer\\/input:checked ~ .peer-checked\\/input\\:-rotate-6 {\n  --tw-rotate: -6deg;\n  transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))\n}\n\n.\\[\\&\\:has\\(input\\:checked\\)\\]\\:rotate-180:has(input:checked) {\n  --tw-rotate: 180deg;\n  transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))\n}"
