    "css": ".sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0, 0, 0, 0);white-space:nowrap;border-width:0}.relative{position:relative}.inline-flex{display:inline-flex}.h-14{height:3.5rem}.w-28{width:7rem}.cursor-pointer{cursor:pointer}.items-center{align-items:center}.bg-blue-300{--tw-bg-opacity:1;background-color:rgb(147 197 253 / var(--tw-bg-opacity))}.outline-none{outline:2px solid transparent;outline-offset:2px}.duration-100{transition-duration:100ms}.after\\:absolute::after{content:var(--tw-content);position:absolute}.after\\:left-1::after{content:var(--tw-content);left:0.25rem}.after\\:top-1::after{content:var(--tw-content);top:0.25rem}.after\\:flex::after{content:var(--tw-content);display:flex}.after\\:h-12::after{content:var(--tw-content);height:3rem}.after\\:w-12::after{content:var(--tw-content);width:3rem}.after\\:items-center::after{content:var(--tw-content);align-items:center}.after\\:justify-center::after{content:var(--tw-content);justify-content:center}.after\\:bg-white::after{content:var(--tw-content);--tw-bg-opacity:1;background-color:rgb(255 255 255 / var(--tw-bg-opacity))}.after\\:font-bold::after{content:var(--tw-content);font-weight:700}.after\\:text-sky-800::after{content:var(--tw-content);--tw-text-opacity:1;color:rgb(7 89 133 / var(--tw-text-opacity))}.after\\:outline-none::after{content:var(--tw-content);outline:2px solid transparent;outline-offset:2px}.after\\:duration-500::after{content:var(--tw-content);transition-duration:500ms}.after\\:content-\\[\\'No\\'\\]::after{--tw-content:'No';content:var(--tw-content)}.peer:checked ~ .peer-checked\\:after\\:translate-x-14::after{content:var(--tw-content);--tw-translate-x:3.5rem;transform:translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))}.peer:checked ~ .peer-checked\\:after\\:border-white::after{content:var(--tw-content);--tw-border-opacity:1;border-color:rgb(255 255 255 / var(--tw-border-opacity))}.peer:checked ~ .peer-checked\\:after\\:content-\\[\\'Yes\\'\\]::after{--tw-content:'Yes';content:var(--tw-content)}.peer:focus ~ .peer-focus\\:outline-none{outline:2px solid transparent;outline-offset:2px}.peer:focus ~ .peer-focus\\:ring-4{--tw-ring-offset-shadow:var(--tw-ring-inset) 0 0 0 var(--tw-ring-offset-width) var(--tw-ring-offset-color);--tw-ring-shadow:var(--tw-ring-inset) 0 0 0 calc(4px + var(--tw-ring-offset-width)) var(--tw-ring-color);box-shadow:var(--tw-ring-offset-shadow), var(--tw-ring-shadow), var(--tw-shadow, 0 0 #0000)}.peer:focus ~ .peer-focus\\:ring-blue-500{--tw-ring-opacity:1;--tw-ring-color:rgb(59 130 246 / var(--tw-ring-opacity))}"
